function txt(s, size, weight, color, w, font){
  const t = figma.createText();
  t.fontName = {family: font||"Poppins", style: weight||"Regular"};
  t.characters = s;
  t.fontSize = size;
  t.fills = [{type:"SOLID", color: color||COLORS.text}];
  if(w) { t.resize(w, t.height); t.textAutoResize="HEIGHT"; }
  return t;
}
function rect(w,h,color,radius){
  const r = figma.createRectangle();
  r.resize(w,h);
  r.fills = color ? [{type:"SOLID", color}] : [];
  if(radius) r.cornerRadius = radius;
  return r;
}
function frameAutoV(name, gap, pad){
  const f = figma.createFrame();
  f.name = name;
  f.layoutMode = "VERTICAL";
  f.itemSpacing = gap||0;
  f.paddingTop = f.paddingBottom = f.paddingLeft = f.paddingRight = pad||0;
  f.primaryAxisSizingMode="AUTO";
  f.counterAxisSizingMode="AUTO";
  f.fills=[];
  return f;
}
function frameAutoH(name, gap, pad){
  const f = frameAutoV(name,gap,pad);
  f.layoutMode="HORIZONTAL";
  return f;
}
async function inst(nodeId){
  const n = await figma.getNodeByIdAsync(nodeId);
  if(!n) return null;
  return n.createInstance ? n.createInstance() : null;
}

// Screen frame factory
function screenFrame(name, h){
  const f = figma.createFrame();
  f.name = name;
  f.resize(375, h);
  f.fills=[{type:"SOLID", color: COLORS.bg}];
  f.clipsContent = true;
  return f;
}

async function addShell(f, dark){
  const sb = await inst("1:33"); // Status Bar
  if(sb){ sb.x=0; sb.y=0; f.appendChild(sb); }
  const hi = await inst("1:43"); // Home Indicator
  if(hi){ hi.x=0; hi.y=f.height-34; f.appendChild(hi); }
}

function roundBtn(){
  const g = figma.createFrame();
  g.name="RoundNextButton";
