async function header(title, withBack, withCart){
  const h = figma.createFrame();
  h.name="Header";
  h.resize(375,80);
  h.fills=[];
  h.layoutMode="HORIZONTAL";
  h.primaryAxisAlignItems="CENTER";
  h.counterAxisAlignItems="CENTER";
  h.primaryAxisSizingMode="FIXED";
  h.counterAxisSizingMode="FIXED";
  h.paddingLeft=20; h.paddingRight=20; h.paddingTop=54; h.itemSpacing=0;
  h.primaryAxisAlignItems="SPACE_BETWEEN";
  if(withBack){
    const b = await inst("2:13");
    if(b){ b.resize(24,24); h.appendChild(b); }
  } else {
    const spacer = figma.createFrame(); spacer.resize(24,24); spacer.fills=[]; h.appendChild(spacer);
  }
  const t = txt(title, 18, "SemiBold", COLORS.text);
  h.appendChild(t);
  if(withCart){
    const c = await inst("2:14");
    if(c){ c.resize(26,26); h.appendChild(c); }
  } else {
    const spacer = figma.createFrame(); spacer.resize(24,24); spacer.fills=[]; h.appendChild(spacer);
  }
  return h;
}
