function txt(s,size,weight,color,w,font){
  const t=figma.createText();
  t.fontName={family:font||"Poppins",style:weight||"Regular"};
  t.characters=s; t.fontSize=size;
  t.fills=[{type:"SOLID",color:color||COLORS.text}];
  if(w){t.resize(w,t.height); t.textAutoResize="HEIGHT";}
  return t;
}
function rect(w,h,color,radius){
  const r=figma.createRectangle(); r.resize(w,h);
  r.fills=color?[{type:"SOLID",color}]:[]; if(radius) r.cornerRadius=radius;
  return r;
}
async function inst(id){ const n=await figma.getNodeByIdAsync(id); return n&&n.createInstance?n.createInstance():null; }
