function setReaction(sourceNode, targetFrameName, navigation){
  const dest = byName[targetFrameName];
  if(!dest){ return false; }
  sourceNode.reactions = [{
    trigger:{type:"ON_CLICK"},
    actions:[{type:"NODE", destinationId: dest.id, navigation: navigation||"NAVIGATE", transition:null, preserveScrollPosition:false}]
  }];
  return true;
}

const results = [];
function tryLink(frameName, nodeName, target){
  const f = byName[frameName];
  if(!f){ results.push("missing frame "+frameName); return; }
  const node = f.findOne(n=>n.name===nodeName);
  if(!node){ results.push("missing node "+nodeName+" in "+frameName); return; }
  const ok = setReaction(node, target);
  results.push((ok?"OK ":"FAIL ")+frameName+"."+nodeName+" -> "+target);
}

