async function wireTabBar(frameName){
  const f = byName[frameName];
  const tb = f.findOne(n=>n.name==="TabBar");
  const storeIcon = tb.findOne(n=>n.name==="Icon_Tab_Store");
  const rewardsIcon = tb.findOne(n=>n.name==="Icon_Tab_Rewards");
  const ordersIcon = tb.findOne(n=>n.name==="Icon_Tab_Orders");
  if(frameName!=="06_Menu") await linkNode(storeIcon,"06_Menu");
  if(frameName!=="18_Rewards") await linkNode(rewardsIcon,"18_Rewards");
  if(frameName!=="20_My_Orders") await linkNode(ordersIcon,"20_My_Orders");
}

